import base64

# 你提供的完整文本（包含 data:image/jpeg;base64, 前缀）
data_uri = "!data:image/jpeg;base64,"

# 去掉前缀
b64_data = data_uri.split(",", 1)[1]

# 解码并保存为图片文件
with open(r"G:\PY_SD\SD\ZK\shopkeeper_brain\knowledge\test\import_process\pyoutput.jpg", "wb") as f:
    f.write(base64.b64decode(b64_data))

print("图片已保存为 output.jpg")